111	/// Runs the sort enforcement optimizer and asserts the plan
112	/// against the original and expected plans
113	///
114	/// `$EXPECTED_PLAN_LINES`: input plan
115	/// `$EXPECTED_OPTIMIZED_PLAN_LINES`: optimized plan
116	/// `$PLAN`: the plan to optimized
117	/// `REPARTITION_SORTS`: Flag to set `config.options.optimizer.repartition_sorts` option.
118	///
119	macro_rules! assert_optimized {
120	    ($EXPECTED_PLAN_LINES: expr, $EXPECTED_OPTIMIZED_PLAN_LINES: expr, $PLAN: expr, $REPARTITION_SORTS: expr) => {
121	        let mut config = ConfigOptions::new();
122	        config.optimizer.repartition_sorts = $REPARTITION_SORTS;
123	
124	        // This file has 4 rules that use tree node, apply these rules as in the
125	        // EnforceSorting::optimize implementation
126	        // After these operations tree nodes should be in a consistent state.
127	        // This code block makes sure that these rules doesn't violate tree node integrity.
128	        {
129	            let plan_requirements = PlanWithCorrespondingSort::new_default($PLAN.clone());
130	            let adjusted = plan_requirements
131	                .transform_up(ensure_sorting)
132	                .data()
133	                .and_then(check_integrity)?;
134	            // TODO: End state payloads will be checked here.
135	
136	            let new_plan = if config.optimizer.repartition_sorts {
137	                let plan_with_coalesce_partitions =
138	                    PlanWithCorrespondingCoalescePartitions::new_default(adjusted.plan);
139	                let parallel = plan_with_coalesce_partitions
140	                    .transform_up(parallelize_sorts)
141	                    .data()
142	                    .and_then(check_integrity)?;
143	                // TODO: End state payloads will be checked here.
144	                parallel.plan
145	            } else {
146	                adjusted.plan
147	            };
148	
149	            let plan_with_pipeline_fixer = OrderPreservationContext::new_default(new_plan);
150	            let updated_plan = plan_with_pipeline_fixer
151	                .transform_up(|plan_with_pipeline_fixer| {
152	                    replace_with_order_preserving_variants(
153	                        plan_with_pipeline_fixer,
154	                        false,
155	                        true,
156	                       &config,
157	                    )
158	                })
159	                .data()
160	                .and_then(check_integrity)?;
161	            // TODO: End state payloads will be checked here.
162	
163	            let mut sort_pushdown = SortPushDown::new_default(updated_plan.plan);
164	            assign_initial_requirements(&mut sort_pushdown);
165	            check_integrity(pushdown_sorts(sort_pushdown)?)?;
166	            // TODO: End state payloads will be checked here.
167	        }
168	
169	        let physical_plan = $PLAN;
170	        let formatted = displayable(physical_plan.as_ref()).indent(true).to_string();
171	        let actual: Vec<&str> = formatted.trim().lines().collect();
172	
173	        let expected_plan_lines: Vec<&str> = $EXPECTED_PLAN_LINES
174	            .iter().map(|s| *s).collect();
175	
176	        assert_eq!(
177	            expected_plan_lines, actual,
178	            "\n**Original Plan Mismatch\n\nexpected:\n\n{expected_plan_lines:#?}\nactual:\n\n{actual:#?}\n\n"
179	        );
180	
181	        let expected_optimized_lines: Vec<&str> = $EXPECTED_OPTIMIZED_PLAN_LINES
182	            .iter().map(|s| *s).collect();
183	
184	        // Run the actual optimizer
185	        let optimized_physical_plan =
186	            EnforceSorting::new().optimize(physical_plan,&config)?;
187	
188	        // Get string representation of the plan
189	        let actual = get_plan_string(&optimized_physical_plan);
190	        assert_eq!(
191	            expected_optimized_lines, actual,
192	            "\n**Optimized Plan Mismatch\n\nexpected:\n\n{expected_optimized_lines:#?}\nactual:\n\n{actual:#?}\n\n"
193	        );
194	
195	    };
